<?php

use PHPUnit\Framework\TestCase;

class UpdatePasswordTest extends TestCase
{
    public function testPasswordUpdate()
    {
        // Simulate a logged-in user session
        $_SESSION['player']['id'] = 1;

        // Simulate the form submission with the relevant data
        $_POST['update_pass'] = 'old_password';
        $_POST['new_pass'] = 'new_password';
        $_POST['confirm_pass'] = 'new_password';
        $_POST['update_info'] = true;

        // Capture the output generated by the script
        ob_start();
        include 'path/to/update-password.php';
        $output = ob_get_clean();

        // Perform assertions to check the expected output or behavior
        $this->assertStringContainsString('<script>alert("Password updated successfully! :)")</script>', $output);

        // Check if the password was actually updated in the database
        global $conn;
        $user_id = $_SESSION['player']['id'];
        $query = "SELECT password FROM `player` WHERE id = '$user_id'";
        $result = mysqli_query($conn, $query);
        $row = mysqli_fetch_assoc($result);
        $updatedPassword = $row['password'];

        // Verify that the updated password matches the hashed value of 'new_password'
        $this->assertTrue(password_verify('new_password', $updatedPassword));
    }
}
